class Command(BaseCommand):
    help = 'Load the Constitution of Kenya, 2010 into the database.'

    def handle(self, *args, **options):
        self.stdout.write('Loading Constitution of Kenya, 2010...')

        Chapter.objects.all().delete()
        Article.objects.all().delete()
        Schedule.objects.all().delete()

        for idx, ch_data in enumerate(CONSTITUTION):
            chapter = Chapter.objects.create(
                number=ch_data['number'],
                title=ch_data['title'],
                subtitle=ch_data.get('subtitle', ''),
                overview=ch_data.get('overview', ''),
                order=idx,
            )
            for art_idx, (art_num, art_title, art_content) in enumerate(ch_data['articles']):
                Article.objects.create(
                    chapter=chapter,
                    number=art_num,
                    title=art_title,
                    content=art_content,
                    order=art_idx,
                )
            self.stdout.write(f'  Chapter {chapter.number}: {chapter.title} ({chapter.article_count} articles)')

        for idx, s_data in enumerate(SCHEDULES):
            Schedule.objects.create(
                number=s_data['number'],
                title=s_data['title'],
                content=s_data['content'],
                order=idx,
            )
            self.stdout.write(f'  Schedule {s_data["number"]}: {s_data["title"]}')

        self.stdout.write(self.style.SUCCESS(
            f'Loaded {Chapter.objects.count()} chapters, {Article.objects.count()} articles, and {Schedule.objects.count()} schedules.'
        ))
